    private void Manual() { for (int i = 0; i < 20 && S.Encounter?.Status == "active"; i++) { var b = S.Encounter; var next = b.Queue.Count > 0 ? b.Units.Find(u => u.Id == b.Queue[0]) : b.Units.Where(u => u.Hp > 0).OrderByDescending(u => u.Stats.Speed).ThenBy(u => u.Id, StringComparer.Ordinal).First(); if (next?.Side == "ally" && next.Hp > 0) { StepBattle(_manualAction); break; } StepBattle(); } }
