    private void Summon() { _region = Math.Min(_region, Math.Min(3, Rules.MaxClear(S) / 30)); Heading("SUMMON / 招贤台", "十契一席，故人可期", "前九抽随机，第十抽三选一。有缺员时至少一位新人可选；满池后定向30片。"); Select(_body, Enumerable.Range(0, Math.Min(4, Rules.MaxClear(S) / 30 + 1)).Select(i => (i.ToString(), Catalog.Regions[i])), _region.ToString(), v => { _region = int.Parse(v); Render(); }); var banner = Panel(_body); var row = Row(banner); var copy = VBox(row); Text(copy, "以契为引，与英杰重逢", 30, _gold); Text(copy, "没有每日任务，没有限时卡池。\n稀有SSR与UR的角色及碎片只来自剧情。", 16, _muted); var buttons = Row(copy); Button(buttons, $"招贤 {10 - S.Draws[_region] % 10} 次", () => Try(new("draw", Number: _region)), true, tag: "draw-pack"); Button(buttons, "单次招贤", () => Try(new("draw", Number: _region, Single: true))); Text(copy, $"持有 {S.Resources["ticket"]} 券 · 本轮 {S.Draws[_region] % 10}/10", 14, _muted); Image(row, "building.summon", 250, 190); var eligible = _catalog.Heroes.Where(h => h.Region == _region && !h.Story).ToList(); Select(_body, eligible.Select(h => (h.Id, h.Name + (S.Heroes.ContainsKey(h.Id) ? " · 培养" : " · 未拥有"))), S.Wishlist[_region] ?? eligible[0].Id, v => Try(new("wish", v, _region))); Text(_body, "许愿只影响三选一优先项。前九抽：整卡60% / 20碎片40%；N15%、R45%、SR35%、普通SSR5%。", 12, _muted); var grid = new GridContainer { Columns = 6, SizeFlagsHorizontal = SizeFlags.ExpandFill }; _body.AddChild(grid); foreach (var h in eligible) HeroCard(grid, h, () => { Try(new("wish", h.Id, _region)); Notice("已许愿：" + h.Name); }); }
    private void Bag() { Heading("TREASURY / 宗门宝库", "一器一策，百战成锋", "四部位、两件同名套装。强化必成，最高+10；已装备与锁定装备不能分解。"); Select(_body, S.Heroes.Keys.Select(id => (id, "穿戴给 " + _catalog.ById[id].Name)), _hero, v => _hero = v); var craft = Panel(_body); Text(craft, "定向锻造 · 50矿石 + 350铜钱", 20); var row = Row(craft); Select(row, Catalog.Slots.Select(id => (id, Catalog.SlotNames[id])), _craftSlot, v => _craftSlot = v); Select(row, Catalog.Sets.Select(x => (x, x)), _craftSet, v => _craftSet = v); Button(row, "锻造", () => Try(new("craft", _craftSlot, Other: _craftSet)), true, !S.Buildings.ContainsKey("forge")); Text(craft, "两件套：破军攻击+15% / 长生生命+15% / 玄策法攻+15% / 流风速度+15", 12, _muted); if (S.Inbox.Count > 0) Button(_body, $"领取溢出保管 {S.Inbox.Count} 件", () => Try(new("inbox"))); Text(_body, $"装备 {S.Items.Count}/500", 16, _gold); var grid = new GridContainer { Columns = 3, SizeFlagsHorizontal = SizeFlags.ExpandFill }; _body.AddChild(grid); foreach (var it in S.Items.AsEnumerable().Reverse()) { var panel = Panel(grid); var title = Row(panel); Image(title, "icon." + it.Slot, 50, 50); Text(title, $"{it.Name} +{it.Enhance}", 19, _gold); Text(panel, $"{new[] { "", "普通", "精良", "史诗" }[it.Quality]} · 装等{it.Level} · 主属性 {Rules.Round(it.Power * (1 + it.Enhance * .12))}\n词缀 {it.Affix.Key} +{it.Affix.Value}", 13, _muted); var owner = S.Heroes.Values.FirstOrDefault(h => h.Equipment.ContainsValue(it.Id)); Text(panel, owner == null ? "背包中" : "持有者：" + _catalog.ById[owner.Id].Name, 12, _jade); var actions = Row(panel); Button(actions, "穿戴", () => Try(new("equip", _hero, Other: it.Id)), true); Button(actions, "强化", () => Try(new("enhance", it.Id))); Button(actions, it.Locked ? "解锁" : "锁定", () => Try(new("lock", it.Id))); Button(panel, "分解", () => Try(new("dismantle", it.Id)), disabled: owner != null || it.Locked); } if (S.Items.Count == 0) Text(_body, "宝库尚待充盈。通关获得装备，第5关开放定向锻造。", 20, _muted); }
    private void DispatchPanel(Node parent) { if (S.Dispatch is not { } d) return; var panel = Panel(parent); Text(panel, $"第 {d.Stage} 关委托 · {(d.Paused ? "已暂停" : "执行中")}", 20, _jade); Text(panel, $"当前 {d.Elapsed / 60000}/{d.CycleMs / 60000} 分钟 · 已完成 {d.Index} 轮\n每小时60券；离线最多48小时。", 13, _muted); var row = Row(panel); if (d.Paused) Button(row, "恢复委托", () => Try(new("dispatch-resume"))); Button(row, "结束委托", () => Try(new("dispatch-stop"))); }
    private void Sect() { Heading("SANCTUM / 随身洞天", "方寸之间，自成山河", "首通解锁建筑，三级即时升级。无人也产出，派驻翻倍；出战自动离岗。"); DispatchPanel(_body); var dispatch = Panel(_body); Text(dispatch, "已通关委托", 20); var row = Row(dispatch); var cleared = S.Cleared.Order().ToList(); if (cleared.Count > 0) { if (!cleared.Contains(_dispatchStage)) _dispatchStage = cleared[^1]; Select(row, cleared.Select(n => (n.ToString(), $"第{n}关" + (n % 10 == 0 ? " · Boss" : ""))), _dispatchStage.ToString(), v => _dispatchStage = int.Parse(v)); Button(row, "开始委托", () => Try(new("dispatch", Number: _dispatchStage)), true, S.Dispatch != null || S.Encounter != null); } else Text(dispatch, "先完成一关，即可开启委托。", 14, _muted); Text(dispatch, "普通关10分钟/10券，Boss30分钟/30券。主动挑战暂停原委托并保留进度，返回后手动恢复。", 13, _muted); var grid = new GridContainer { Columns = 3, SizeFlagsHorizontal = SizeFlags.ExpandFill }; _body.AddChild(grid); foreach (var b in _catalog.Buildings) { var panel = Panel(grid); int level = S.Buildings.GetValueOrDefault(b.Id); Image(panel, b.Asset, 240, 145); Text(panel, b.Name + (level > 0 ? $"   Lv.{level}/3" : $"   第{b.Unlock}关开放"), 20, _gold); Text(panel, b.Desc, 13, _muted); if (level > 0) { Text(panel, b.Id == "summon" ? "招贤契约永久开放" : $"每2分钟产出 {level * (b.Resource == "gold" ? 45 : b.Resource == "xp" ? 35 : 4)} {b.Resource}，派驻×2", 12, _jade); Select(panel, new[] { ("", "无人值守") }.Concat(S.Heroes.Keys.Select(id => (id, _catalog.ById[id].Name))), S.Workers.GetValueOrDefault(b.Id) ?? "", v => Try(new("worker", b.Id, Other: v == "" ? null : v))); Button(panel, level >= 3 ? "已满级" : $"升级 · {800 * level}铜钱 / {60 * level}矿石", () => Try(new("building", b.Id)), disabled: level >= 3); } else panel.Modulate = new Color(1, 1, 1, .4f); } }
    private void StoryPage() { Heading("CHRONICLE / 异界绘卷", "故人入卷，归途渐明", "主线名册96人全部结识，并战胜第120关归墟之主，返回现世。"); var prologue = Panel(_body); Text(prologue, "你醒来时，掌心多了一方洞天。", 26, _gold); Text(prologue, "历史的山河真实得触手可及。散落在异界的英杰，都是世界碎裂前的回响。与他们结缘，让所有名字重新聚拢；然后去归墟，打破最后的封印。", 15, _muted); Text(prologue, $"名册 {S.Heroes.Count}/96     剧情结缘 {S.Story.Count}/24     终战 {(S.Cleared.Contains(120) ? "已胜利" : "等待挑战")}", 17, _jade); if (S.Ending) Button(prologue, "重温返回现实结局", EndingDialog, true); var grid = new GridContainer { Columns = 3, SizeFlagsHorizontal = SizeFlags.ExpandFill }; _body.AddChild(grid); foreach (var h in _catalog.Heroes.Where(x => x.Story)) { var panel = Panel(grid); var row = Row(panel); Image(row, h.Asset, 80, 110); var info = VBox(row); Text(info, h.Name + " · " + h.Rarity, 21, _gold); Text(info, $"第{h.Unlock}关 · {Catalog.Regions[h.Region]}", 12, _muted); if (!S.Story.Contains(h.Id)) Button(panel, "阅读剧情 · 结缘", () => StoryDialog(h), true, Rules.MaxClear(S) < h.Unlock); else { int trial = S.Trials.GetValueOrDefault(h.Id); Button(panel, $"个人历练 {trial}/5", () => TrialDialog(h), disabled: trial == 5); Button(panel, "查看名将", () => { _hero = h.Id; _page = "heroes"; Render(); }); } } }
    private void Settings() { Heading("SYSTEM / 设置", "把归途，妥善保存", "原生文件存档，自动保存与上一版备份。可导入浏览器v0.1.0导出文件。"); var panel = Panel(_body); Text(panel, "存档位置", 22, _gold); Text(panel, _savePath, 13, _muted); var row = Row(panel); Button(row, "导出存档", () => FileDialog(false), true); Button(row, "导入存档", () => FileDialog(true)); Button(row, "读取自动备份", () => Confirm("读取自动备份", "将回退到上一版保存状态。建议先导出当前存档。", () => { try { var loaded = SaveCodec.Decode(_catalog, System.IO.File.ReadAllText(_savePath + ".backup")); _engine.Import(loaded); CloseDialog(); Render(); Notice("已恢复备份。"); } catch (Exception e) { Notice(e.Message); } })); Button(row, "打开存档目录", () => OS.ShellOpen(System.IO.Path.GetDirectoryName(_savePath)!)); Button(panel, _sound ? "关闭占位音效" : "开启占位音效", () => { _sound = !_sound; Render(); }); Text(panel, "Godot 4.5 .NET / .NET 8 / C# 原生逻辑\n不使用WebView，不依赖JavaScript运行时。", 17, _jade); Text(panel, "人物、敌人、建筑、场景、装备、UI、特效和音频位于Assets。修改manifest.json即可替换素材。正式剧情、人物独有技能与商业平衡仍需继续制作。", 14, _muted); Button(panel, "打开工程资源目录", () => OS.ShellOpen(ProjectSettings.GlobalizePath("res://Assets"))); }
    private void ShowDialog(string title, Action<VBoxContainer> build, bool required = false, int width = 720, int height = 570) { CloseDialog(); _dialog = new Window { Title = title, Size = new Vector2I(width, height), Transient = true, Exclusive = true, Unresizable = false, Theme = _theme }; AddChild(_dialog); var m = new MarginContainer(); m.SetAnchorsAndOffsetsPreset(LayoutPreset.FullRect); foreach (var side in new[] { "left", "right", "top", "bottom" }) m.AddThemeConstantOverride("margin_" + side, 25); _dialog.AddChild(m); var scroll = new ScrollContainer { SizeFlagsHorizontal = SizeFlags.ExpandFill, SizeFlagsVertical = SizeFlags.ExpandFill, HorizontalScrollMode = ScrollContainer.ScrollMode.Disabled }; m.AddChild(scroll); var v = VBox(scroll, 15); Text(v, title, 26, _gold); build(v); _dialog.CloseRequested += () => { if (!required) CloseDialog(); }; _dialog.PopupCentered(); }
    private void CloseDialog() { if (_dialog != null) { _dialog.Hide(); _dialog.QueueFree(); _dialog = null; } _offerId = null; }
    private void OfferDialog() { var offer = S.Pending!; ShowDialog(offer.Kind == "loot" ? "首领首通 · 构筑宝箱" : "招贤席 · 请君择一", v => { Text(v, "本席已预付，关闭游戏也会保存原候选。选择一项，不额外扣费。", 14, _muted); var row = Row(v); for (int i = 0; i < offer.Options.Count; i++) { int index = i; var o = offer.Options[i]; var card = VBox(row); if (offer.Kind == "recruit") { HeroCard(card, _catalog.ById[o.Id], () => Try(new("choose", offer.Id, Index: index))); Text(card, o.Type == "hero" && !S.Heroes.ContainsKey(o.Id) ? "结识新人物" : $"培养碎片 ×{o.Amount}", 14, _jade); } else { Image(card, "icon." + o.Item!.Slot, 120, 120); Text(card, o.Item.Name, 21); Text(card, $"史诗 · 装等{o.Item.Level}\n主属性{o.Item.Power}", 14, _muted); } Button(card, "选择这一项", () => Try(new("choose", offer.Id, Index: index)), true, tag: "offer-choice-" + index); } if (offer.Results.Count > 0) Text(v, "已入账：" + string.Join("、", offer.Results.Select(x => _catalog.ById[x.Id].Name + (x.IsNew ? "（新）" : "×20片"))), 12, _muted); }, true, 800, 570); _offerId = offer.Id; }
    private void FormationDialog(int slot) { ShowDialog($"选择{(slot < 3 ? "前" : "后")}排名将", v => { Text(v, "同一人物不重复占格；已上阵人物与目标位置交换。", 14, _muted); var grid = new GridContainer { Columns = 4, SizeFlagsHorizontal = SizeFlags.ExpandFill }; v.AddChild(grid); foreach (var id in S.Heroes.Keys) HeroCard(grid, _catalog.ById[id], () => { CloseDialog(); Try(new("formation", id, slot)); }); Button(v, "清空该阵位", () => { CloseDialog(); Try(new("formation", Number: slot)); }); }, width: 820, height: 650); }
    private void StoryDialog(HeroDef h) { ShowDialog("结缘 · " + h.Name, v => { Image(v, h.Asset, 180, 210); Text(v, $"“山河虽异，心中之志未改。宗主，愿与你同行，寻回众人的归途。”\n\n你以洞天为誓，邀其同探归墟。{h.Name}轻轻颔首，一个新的名字在归途名册上亮起。", 18); Button(v, "邀请加入洞天", () => { CloseDialog(); Try(new("story", h.Id)); }, true); }); }
    private void TrialDialog(HeroDef h) { int i = S.Trials.GetValueOrDefault(h.Id); ShowDialog(h.Name + " · 个人历练", v => { Text(v, $"第{i + 1}项历练\n主线通关第{Math.Max(h.Unlock, Catalog.Gates[i])}关\n人物达到{Catalog.Caps[i]}级\n消耗{20 * (i + 1)}灵草\n获得{Catalog.Costs[i]}本人碎片", 20); Text(v, "每项只完成一次，无日期限制。当前为条件历练；独立人物战斗属于后续内容制作。", 13, _muted); Button(v, "完成历练", () => { CloseDialog(); Try(new("trial", h.Id)); }, true); }); }
    private void EndingDialog() => ShowDialog("终章 · 此间山河，来日再会", v => { Text(v, "九十六个名字化为星光，归墟不再吞噬往昔。你终于推开回到现实的门。\n\n“宗主，若有来日，愿再同行。”\n\n你睁开眼睛。屏幕上仍是熟悉的标题，掌心却留着一枚温热的玉印。旅途已经完成，洞天依然为你保留。", 20); Button(v, "留在洞天继续探索", CloseDialog, true); });
    private void Confirm(string title, string text, Action action) => ShowDialog(title, v => { Text(v, text, 18); Button(v, "确认", action, true); Button(v, "取消", CloseDialog); }, height: 310);
    private void FileDialog(bool import) { var d = new Godot.FileDialog { Title = import ? "导入存档" : "导出存档", Access = Godot.FileDialog.AccessEnum.Filesystem, FileMode = import ? Godot.FileDialog.FileModeEnum.OpenFile : Godot.FileDialog.FileModeEnum.SaveFile, Filters = ["*.json ; SHUABAO save"], CurrentFile = import ? "" : "SHUABAO-Godot.save.json", Size = new Vector2I(850, 600), Theme = _theme }; AddChild(d); d.FileSelected += path => { try { if (import) { var state = SaveCodec.Decode(_catalog, System.IO.File.ReadAllText(path)); Confirm("导入存档", $"将载入{state.Heroes.Count}位名将、已通关{Rules.MaxClear(state)}关的存档。当前进度保留为备份。", () => { try { _engine.Import(state); CloseDialog(); _stage = Math.Min(120, Rules.MaxClear(S) + 1); _region = (_stage - 1) / 30; Render(); Notice("存档已载入。"); } catch (Exception e) { Notice(e.Message); } }); } else { System.IO.File.WriteAllText(path, SaveCodec.Encode(S)); Notice("已导出存档：" + path); } } catch (Exception e) { Notice(e.Message); } d.QueueFree(); }; d.Canceled += () => d.QueueFree(); d.PopupCentered(); }
    private void Sound(string name) { if (!_sound) return; var player = new AudioStreamPlayer { Stream = _assets.Audio("audio." + name), VolumeDb = -15 }; AddChild(player); player.Finished += () => player.QueueFree(); player.Play(); }
    private void ShowFatal(Exception error) { GD.PushError(error.ToString()); if (_smoke) { GetTree().Quit(1); return; } foreach (var child in GetChildren()) child.QueueFree(); var v = VBox(this); Text(v, "暂时无法展开绘卷", 30, _gold); Text(v, error.Message + "\n现有存档没有清空。若已有另一实例在运行，请先关闭它。", 18); Button(v, "打开存档目录", () => OS.ShellOpen(System.IO.Path.GetDirectoryName(_savePath) ?? ProjectSettings.GlobalizePath("user://"))); Button(v, "退出", () => GetTree().Quit()); }
    private async void Smoke() { try { var pages = new[] { "battle", "heroes", "summon", "bag", "sect", "story", "settings" }; foreach (var page in pages) { _page = page; Render(); await ToSignal(GetTree(), SceneTree.SignalName.ProcessFrame); } Try(new("draw", Number: 0)); Rules.Require(S.Pending != null, "招募界面没有生成选择"); var before = SaveCodec.Encode(S); var restored = SaveCodec.Decode(_catalog, before); Rules.Require(restored.Pending!.Id == S.Pending!.Id, "未决选择恢复失败"); Try(new("choose", S.Pending.Id, Index: 0)); var ids = S.Heroes.Keys.Take(6).ToArray(); for (int i = 0; i < ids.Length; i++) Try(new("formation", ids[i], i), false); _page = "battle"; Try(new("battle", Number: 1)); for (int i = 0; i < 1000 && S.Encounter?.Status == "active"; i++) _engine.Execute(new("step"), Now); Rules.Require(S.Encounter?.Status == "victory", "首关未胜利"); var reward = (Reward)_engine.Execute(new("settle"), Now)!; Rules.Require(reward.Tickets == 10, "首关奖励非10券"); Try(new("dispatch", Number: 1)); foreach (var page in pages) { _page = page; Render(); await ToSignal(GetTree(), SceneTree.SignalName.ProcessFrame); } GD.Print("SHUABAO_GODOT_SMOKE_PASS: 7 pages, recruit, choice recovery, formation, three-wave win, dispatch"); GetTree().Quit(); } catch (Exception e) { GD.PushError(e.ToString()); GetTree().Quit(1); } }
